      "status": "PARTIAL",
      "evidence": "R12 fact register 僅出現 0026 相關 FACT ID，未見 0022～0025 正文複製；但候選本文缺席，不能確認交接僅為文件 ID／通用引用。"
    },
    "authority_state_boundaries": {
      "status": "PARTIAL",
      "evidence": "FACT-0026-013 標『TOP 知會備查（非核准）』有利於核可狀態分离；然封面『PENDING_APPROVAL / CANDIDATE』及表單六 TR-07『PENDING_APPROVAL』是否已移除，無候選正文可核。"
    },
    "synthetic_truth_and_coherence": {
      "status": "PARTIAL_PASS_REGISTER_ONLY",
      "evidence": "Register 層次數值自洽：25+3=28；12/12=100.0%；4/4=100.0%；1,650 秒=27.5 分；27.5/5=5.50 分；22.4/4=5.60 分；14+3=17；FACT-052 標 4 CURRENT+1 CANDIDATE，FACT-053 標非 CURRENT 合規率。此僅為登錄表層次，不代表候選文件一致。"
    },
    "functional_usability": {
      "status": "UNVERIFIABLE",
      "evidence": "無候選正文或已填表單可評估可直接複製使用性與可讀性（字級不在本次語意範圍）。"
    },
