      "evidence": "F-005 於 register 可見更新；F-001～F-004 缺少候選正文證據，未能關閉。"
    }
  },
  "findings": [
    {
      "id": "BLOCK-001",
      "severity": "blocker",
      "location": "review input / packet scope",
      "evidence": "封包提供 candidate_path 與宣告 SHA，但未提供 DOCX 本文、表格或可讀取內容；且明確禁止 commands/tools。獨立審查所需之受審標的缺席。",
      "required_repair": "提供綁定 SHA 56E4449F06C8CF0D4DC13579A386EEEA88E59A8403FF9C1E1EF036FDCAAC7491 之候選 DOCX 可讀內容（或授權唯讀工具讀取），再逐項核對 7.3、表一序號 2/16/17、封面版次／生效日列、表單五 SMP-03、表單六 TR-07。"
    },
    {
      "id": "F-001",
      "severity": "minor",
      "location": "7.3 節應簽收對象分類；表單二 ST-021/ST-022/ST-026 列",
      "evidence": "R11 指出 7.3 列『兼任專案顧問 7 人』但表單二僅 3 名兼任顧問；R12 register 有 FACT-016/019=28 人、FACT-017=25 人、FACT-018=3 人（25+3=28），但未見 7.3 文字或 7→3 之修正證據。",
      "required_repair": "於候選正文對齊 7.3 分類與表單二職稱人數，或明確定義『兼任專案顧問』涵蓋對象，並保持 28 人總數一致。"
    },
    {
      "id": "F-002",
      "severity": "minor",
      "location": "表一序號 2、16、17『示範保存期限』欄",
      "evidence": "R12 register 僅有 FACT-032=3 年、FACT-033=5 年、FACT-034=永久保存、FACT-048=2031-10-16 並註實際年限 UNKNOWN；無序號 2/16/17 之個別欄位值，無法確認候選保存期限處理是否一致。",
      "required_repair": "所有 CANDIDATE 件一致標示保存期限 UNKNOWN，或一致套用 4.9 示範年限並加註『候選示範』。"
    },
    {
      "id": "F-003",
      "severity": "minor",
      "location": "封面版次行；表一序號 2；表單五 SMP-03",
      "evidence": "R12 register 僅見 FACT-009=V1.2、FACT-010=V2.0，未提供封面／表一／SMP-03 之版次標籤；無法確認 V1.0-CANDIDATE 與 V1.0 是否統一。",
      "required_repair": "統一版次欄格式（版號與狀態分欄，或全面加註 -CANDIDATE）。"
    },
    {
      "id": "F-004",
      "severity": "minor",
      "location": "封面最新生效日行；表單六 TR-07；對比 2.5 節狀態定義",
      "evidence": "R12 register 之 FACT-0026-013 明標『TOP 知會備查（非核准）』，方向上支持狀態分離；但封面 PENDING_APPROVAL 標記與表單六 TR-07 候選註記是否移除仍無正文可核。",
      "required_repair": "統一為 CANDIDATE（或 DRAFT），移除 PENDING_APPROVAL 標記，並與 2.5 定義一致。"
    },
    {
      "id": "F-005",
      "severity": "minor",
      "location": "synthetic_fact_register FACT-0026-024；對比 6.2 與表一",
      "evidence": "R12 register 已將 FACT-0026-024 更新為『14 件 CURRENT；總清冊 17 筆；3 件 CANDIDATE（與文件表一及 6.2 一致）』，登錄表層已修正 R11 之 15 筆口徑；候選文件表一／6.2 正文未驗證。",
      "required_repair": "於候選正文確認 6.2 與表一同為 14 CURRENT／3 CANDIDATE／合計 17 筆，並保留口徑說明。"
    },
    {
      "id": "OBS-001",
      "severity": "informational",
      "location": "review packet scope 行",
      "evidence": "scope 行寫『official I04-E04 source』，而 work_id、source_packet、blueprint、官方 PDF 與 R11 皆為 I04-E05；屬封包內部標註不一致，非候選 DOCX 缺陷。",
      "required_repair": "將 scope 行更正為 I04-E05，以避免受審需求誤標。"
    }
  ],
